 /* ── Cart state ───────────────────────────────────────────────── */
 let cartCount = 0;

 const cartBadge  = document.getElementById('cart-badge');
 const cartToast  = document.getElementById('cart-toast');
 const toastMsg   = document.getElementById('toast-msg');
 const cartStatus = document.getElementById('cart-status');
 let toastTimeout;

 function updateCart(productName) {
   cartCount++;
   cartBadge.textContent = cartCount;
   cartBadge.hidden = false;

   const msg = `${productName} added to cart`;
   toastMsg.textContent = msg;
   cartStatus.textContent = msg;           // polite live region

   cartToast.classList.add('visible');
   clearTimeout(toastTimeout);
   toastTimeout = setTimeout(() => cartToast.classList.remove('visible'), 3200);
 }

 /* ── Add-to-cart buttons ─────────────────────────────────────── */
 document.querySelectorAll('[data-add-to-cart]').forEach(btn => {
   btn.addEventListener('click', () => {
     const name = btn.dataset.addToCart;
     updateCart(name);
   });
 });

 /* ── Wishlist buttons ────────────────────────────────────────── */
 document.querySelectorAll('[data-wishlist]').forEach(btn => {
   btn.addEventListener('click', () => {
     const pressed = btn.getAttribute('aria-pressed') === 'true';
     btn.setAttribute('aria-pressed', String(!pressed));
     btn.querySelector('svg').style.fill = !pressed ? 'currentColor' : 'none';
   });
 });

 /* ── Promo banner dismiss ────────────────────────────────────── */
 const promoBanner  = document.getElementById('promo-banner');
 const promoDismiss = document.getElementById('promo-dismiss');
 if (promoDismiss) {
   promoDismiss.addEventListener('click', () => {
     promoBanner.hidden = true;
   });
 }

 /* ── Mobile menu toggle ──────────────────────────────────────── */
 const mobileMenuBtn = document.getElementById('mobile-menu-btn');
 const mobileMenu    = document.getElementById('mobile-menu');
 if (mobileMenuBtn && mobileMenu) {
   mobileMenuBtn.addEventListener('click', () => {
     const expanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';
     mobileMenuBtn.setAttribute('aria-expanded', String(!expanded));
     mobileMenu.hidden = expanded;
   });

   document.addEventListener('keydown', e => {
     if (e.key === 'Escape' && mobileMenuBtn.getAttribute('aria-expanded') === 'true') {
       mobileMenuBtn.setAttribute('aria-expanded', 'false');
       mobileMenu.hidden = true;
       mobileMenuBtn.focus();
     }
   });
 }

 /* ── Countdown timers ────────────────────────────────────────── */
 function startCountdown(containerId, endTime) {
   const el = document.getElementById(containerId);
   if (!el) return;
   const hEl = el.querySelector('[data-h]');
   const mEl = el.querySelector('[data-m]');
   const sEl = el.querySelector('[data-s]');

   function tick() {
     const diff = Math.max(0, endTime - Date.now());
     const h = Math.floor(diff / 3600000);
     const m = Math.floor((diff % 3600000) / 60000);
     const s = Math.floor((diff % 60000) / 1000);
     hEl.textContent = String(h).padStart(2, '0');
     mEl.textContent = String(m).padStart(2, '0');
     sEl.textContent = String(s).padStart(2, '0');
   }
   tick();
   setInterval(tick, 1000);
 }

 startCountdown('timer-1', Date.now() + 4 * 3600000 + 23 * 60000 + 17000);
 startCountdown('timer-2', Date.now() + 1 * 3600000 + 47 * 60000 + 55000);
 startCountdown('timer-3', Date.now() + 11 * 3600000 + 59 * 60000 + 9000);

 /* ── Newsletter form ─────────────────────────────────────────── */
 const newsletterForm   = document.getElementById('newsletter-form');
 const newsletterStatus = document.getElementById('newsletter-status');
 if (newsletterForm) {
   newsletterForm.addEventListener('submit', e => {
     e.preventDefault();
     newsletterStatus.textContent = 'Thanks for subscribing! Check your inbox for a confirmation.';
     newsletterForm.reset();
   });
 }

