*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:      #0d0d0f;
  --bg-surface:   #18181c;
  --bg-raised:    #222228;
  --bg-hover:     #2a2a32;
  --accent:       #e8b14f;
