}

/* ── Layout helpers ───────────────────────────────────────────── */
.container {
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

/* ── Site header / nav ─────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-h);
}

.site-header .container {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 100%;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  color: var(--text-primary);
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.02em;
  flex-shrink: 0;
}

.site-logo svg { color: var(--accent); }

.primary-nav { flex: 1; }

.primary-nav ul {
  list-style: none;
  display: flex;
  align-items: center;
  gap: .25rem;
}

.primary-nav a {
  display: block;
  padding: .375rem .75rem;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.primary-nav a[aria-current="page"] {
  color: var(--accent);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: color var(--transition), background var(--transition), border-color var(--transition);
}

.icon-btn:hover, .icon-btn:focus-visible {
  color: var(--text-primary);
  background: var(--bg-raised);
  border-color: var(--accent);
}

.cart-btn {
  position: relative;
}

.cart-badge {
