  font-size: 1rem;
  font-weight: 600;
  transition: color var(--transition), background var(--transition);
}

.mobile-menu a:hover,
.mobile-menu a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.mobile-menu a[aria-current="page"] {
  color: var(--accent);
}

/* ── Hero ─────────────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #13131a 0%, #1a1a24 50%, #0f0f14 100%);
  padding-block: clamp(4rem, 10vw, 8rem);
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 70% at 70% 50%, rgba(232,177,79,.07) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(100,80,200,.06) 0%, transparent 60%);
  pointer-events: none;
}

.hero .container {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-tag {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(232,177,79,.1);
  border: 1px solid rgba(232,177,79,.25);
  border-radius: 9999px;
  padding: .25rem .75rem;
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}

.hero-title em {
  font-style: normal;
  color: var(--accent);
}

.hero-subtitle {
  font-size: 1.0625rem;
  color: var(--text-muted);
  max-width: 46ch;
  margin-bottom: 2rem;
}

.hero-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--accent);
  color: var(--accent-text);
  font-size: .9375rem;
  font-weight: 700;
  padding: .75rem 1.625rem;
