  line-height: 1.2;
}

.hero-stat-label {
  font-size: .8125rem;
  color: var(--text-muted);
}

/* ── Section base ─────────────────────────────────────────────── */
.section {
  padding-block: clamp(3rem, 7vw, 5.5rem);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-eyebrow {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .4rem;
}

.section-title {
  font-size: clamp(1.5rem, 3.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -.025em;
  line-height: 1.2;
}

.section-desc {
  color: var(--text-muted);
