*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:      #0d0d0f;
  --bg-surface:   #18181c;
  --bg-raised:    #222228;
  --bg-hover:     #2a2a32;
  --accent:       #e8b14f;
  --accent-dim:   #c4923a;
  --accent-text:  #0d0d0f;
  --text-primary: #f0ede8;
  --text-muted:   #9e9b94;
  --text-faint:   #8e8c86;
  --danger:       #e05252;
  --success:      #4caf7d;
  --border:       #2e2e36;
  --radius-sm:    4px;
  --radius-md:    8px;
  --radius-lg:    14px;
  --shadow-card:  0 4px 20px rgba(0,0,0,.45);
  --transition:   .2s ease;
  --max-w:        1280px;
  --nav-h:        64px;
}

html { color-scheme: dark; scroll-behavior: smooth; }

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Skip link ────────────────────────────────────────────────── */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--accent);
  color: var(--accent-text);
  padding: .5rem 1rem;
  font-weight: 700;
  z-index: 9999;
  border-radius: 0 0 var(--radius-sm) 0;
  text-decoration: none;
}

/* ── Focus visible ────────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* ── Layout helpers ───────────────────────────────────────────── */
.container {
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

/* ── Site header / nav ─────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.88);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: var(--nav-h);
}

.site-header .container {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 100%;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  color: var(--text-primary);
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -.02em;
  flex-shrink: 0;
}

.site-logo svg { color: var(--accent); }

.primary-nav { flex: 1; }

.primary-nav ul {
  list-style: none;
  display: flex;
  align-items: center;
  gap: .25rem;
}

.primary-nav a {
  display: block;
  padding: .375rem .75rem;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.primary-nav a[aria-current="page"] {
  color: var(--accent);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  flex-shrink: 0;
}

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: color var(--transition), background var(--transition), border-color var(--transition);
}

.icon-btn:hover, .icon-btn:focus-visible {
  color: var(--text-primary);
  background: var(--bg-raised);
  border-color: var(--accent);
}

.cart-btn {
  position: relative;
}

.cart-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  background: var(--accent);
  color: var(--accent-text);
  font-size: .625rem;
  font-weight: 800;
  line-height: 1;
  padding: 2px 4px;
  border-radius: 9999px;
  min-width: 16px;
  text-align: center;
}

.mobile-menu-btn { display: none; }

/* ── Mobile nav menu ──────────────────────────────────────────── */
.mobile-menu {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: .75rem 0;
}

.mobile-menu ul {
  list-style: none;
  display: flex;
  flex-direction: column;
}

.mobile-menu a {
  display: block;
  padding: .75rem clamp(1rem, 4vw, 2.5rem);
  color: var(--text-muted);
  text-decoration: none;
  font-size: 1rem;
  font-weight: 600;
  transition: color var(--transition), background var(--transition);
}

.mobile-menu a:hover,
.mobile-menu a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.mobile-menu a[aria-current="page"] {
  color: var(--accent);
}

/* ── Hero ─────────────────────────────────────────────────────── */
.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #13131a 0%, #1a1a24 50%, #0f0f14 100%);
  padding-block: clamp(4rem, 10vw, 8rem);
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 70% at 70% 50%, rgba(232,177,79,.07) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(100,80,200,.06) 0%, transparent 60%);
  pointer-events: none;
}

.hero .container {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-tag {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(232,177,79,.1);
  border: 1px solid rgba(232,177,79,.25);
  border-radius: 9999px;
  padding: .25rem .75rem;
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}

.hero-title em {
  font-style: normal;
  color: var(--accent);
}

.hero-subtitle {
  font-size: 1.0625rem;
  color: var(--text-muted);
  max-width: 46ch;
  margin-bottom: 2rem;
}

.hero-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--accent);
  color: var(--accent-text);
  font-size: .9375rem;
  font-weight: 700;
  padding: .75rem 1.625rem;
  border-radius: var(--radius-md);
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--accent-dim);
}

@media (prefers-reduced-motion: no-preference) {
  .btn-primary:hover { transform: translateY(-1px); }
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: transparent;
  color: var(--text-primary);
  font-size: .9375rem;
  font-weight: 600;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-md);
  text-decoration: none;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}

.btn-ghost:hover, .btn-ghost:focus-visible {
  border-color: var(--accent);
  background: var(--bg-raised);
}

.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-img-wrapper {
  position: relative;
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-card), 0 0 80px rgba(232,177,79,.06);
}

.hero-img-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2rem;
}

.hero-stat {
  display: flex;
  flex-direction: column;
}

.hero-stat-number {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.2;
}

.hero-stat-label {
  font-size: .8125rem;
  color: var(--text-muted);
}

/* ── Section base ─────────────────────────────────────────────── */
.section {
  padding-block: clamp(3rem, 7vw, 5.5rem);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-eyebrow {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .4rem;
}

.section-title {
  font-size: clamp(1.5rem, 3.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -.025em;
  line-height: 1.2;
}

.section-desc {
  color: var(--text-muted);
  margin-top: .5rem;
  font-size: .9375rem;
  max-width: 55ch;
}

.see-all-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  color: var(--accent);
  font-size: .9rem;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
  padding: .25rem .5rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition);
}

.see-all-link:hover, .see-all-link:focus-visible {
  color: var(--accent-dim);
  text-decoration: underline;
}

/* ── Product grid ─────────────────────────────────────────────── */
.product-grid {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 240px), 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.product-card:hover {
  border-color: rgba(232,177,79,.3);
  box-shadow: var(--shadow-card);
}

.product-card-img {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--bg-raised);
}

.product-card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform .35s ease;
}

.product-card:hover .product-card-img img {
  transform: scale(1.04);
}

@media (prefers-reduced-motion: reduce) {
  .product-card:hover .product-card-img img { transform: none; }
}

.product-badge {
  position: absolute;
  top: .625rem;
  left: .625rem;
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .2rem .55rem;
  border-radius: 9999px;
}

.badge-new    { background: var(--accent); color: var(--accent-text); }
.badge-sale   { background: var(--danger); color: #fff; }
.badge-hot    { background: #b44fdb; color: #fff; }

.product-card-body {
  padding: 1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-category {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--text-faint);
  margin-bottom: .25rem;
}

.product-name-link {
  text-decoration: none;
  color: var(--text-primary);
}

.product-name-link:hover { color: var(--accent); }

.product-name {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: .5rem;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .375rem;
  margin-bottom: .625rem;
}

.stars {
  display: flex;
  gap: 1px;
  color: var(--accent);
}

.rating-count {
  font-size: .8rem;
  color: var(--text-muted);
}

.product-price-row {
  display: flex;
  align-items: center;
  gap: .625rem;
  margin-top: auto;
  padding-top: .75rem;
  border-top: 1px solid var(--border);
}

.price-current {
  font-size: 1.125rem;
  font-weight: 800;
  color: var(--text-primary);
}

.price-original {
  font-size: .875rem;
  color: var(--text-faint);
  text-decoration: line-through;
}

.price-discount {
  margin-left: auto;
  font-size: .75rem;
  font-weight: 700;
  color: var(--success);
  background: rgba(76,175,125,.1);
  padding: .15rem .45rem;
  border-radius: 9999px;
}

.product-card-footer {
  padding: .75rem 1rem 1rem;
  display: flex;
  gap: .5rem;
}

.add-to-cart-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .375rem;
  background: var(--bg-raised);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  padding: .625rem .75rem;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}

.add-to-cart-btn:hover, .add-to-cart-btn:focus-visible {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}

.wishlist-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background: var(--bg-raised);
  color: var(--text-muted);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
  flex-shrink: 0;
}

.wishlist-btn:hover, .wishlist-btn:focus-visible {
  color: #e05252;
  border-color: #e05252;
  background: rgba(224,82,82,.08);
}

/* ── Deals section ─────────────────────────────────────────────── */
.deals-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.deals-grid {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  position: relative;
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.deal-card::before {
  content: "";
  position: absolute;
  top: 0; right: 0;
  width: 120px; height: 120px;
  background: radial-gradient(circle, rgba(232,177,79,.08) 0%, transparent 70%);
  pointer-events: none;
}

.deal-card:hover {
  border-color: rgba(232,177,79,.35);
  box-shadow: var(--shadow-card);
}

.deal-timer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: .5rem;
}

.deal-tag {
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--danger);
  background: rgba(224,82,82,.12);
  border: 1px solid rgba(224,82,82,.25);
  border-radius: 9999px;
  padding: .2rem .6rem;
}

.deal-timer {
  display: flex;
  gap: .25rem;
  align-items: center;
}

.timer-seg {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .2rem .45rem;
  min-width: 36px;
}

.timer-num {
  font-size: .875rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--text-primary);
}

.timer-label {
  font-size: .6rem;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--text-faint);
}

.timer-sep {
  color: var(--text-muted);
  font-weight: 700;
  align-self: flex-start;
  padding-top: .15rem;
}

.deal-img {
  width: 100%;
  aspect-ratio: 16/9;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-surface);
}

.deal-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.deal-info { flex: 1; }

.deal-name-link {
  text-decoration: none;
  color: var(--text-primary);
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.3;
  display: block;
  margin-bottom: .375rem;
}

.deal-name-link:hover { color: var(--accent); }

.deal-desc { font-size: .875rem; color: var(--text-muted); }

.deal-price-row {
  display: flex;
  align-items: center;
  gap: .75rem;
}

.deal-price { font-size: 1.375rem; font-weight: 800; color: var(--text-primary); }
.deal-original { font-size: .9rem; color: var(--text-faint); text-decoration: line-through; }
.deal-savings {
  font-size: .8125rem;
  font-weight: 700;
  color: var(--success);
  background: rgba(76,175,125,.1);
  padding: .2rem .5rem;
  border-radius: 9999px;
}

.deal-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  background: rgba(232,177,79,.12);
  color: var(--accent);
  border: 1px solid rgba(232,177,79,.3);
  border-radius: var(--radius-md);
  font-size: .9rem;
  font-weight: 700;
  padding: .625rem 1rem;
  cursor: pointer;
  text-decoration: none;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}

.deal-cta:hover, .deal-cta:focus-visible {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}

/* ── Categories strip ─────────────────────────────────────────── */
.categories-strip { padding-block: 2.5rem; }

.categories-list {
  list-style: none;
  display: flex;
  gap: .875rem;
  overflow-x: auto;
  padding-bottom: .5rem;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.category-chip {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .5rem 1rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 9999px;
  color: var(--text-muted);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
  flex-shrink: 0;
}

.category-chip:hover, .category-chip:focus-visible {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-raised);
}

.category-chip-icon {
  font-size: 1.1rem;
  line-height: 1;
}

/* ── Editorial grid ───────────────────────────────────────────── */
.editorial-grid {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

.editorial-grid li:first-child {
  grid-row: span 2;
}

.editorial-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  display: block;
  text-decoration: none;
  color: var(--text-primary);
}

.editorial-card-img {
  width: 100%;
  aspect-ratio: 3/2;
  overflow: hidden;
  background: var(--bg-raised);
}

.editorial-grid li:first-child .editorial-card-img {
  aspect-ratio: auto;
  height: 100%;
  min-height: 220px;
}

.editorial-card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform .4s ease;
}

.editorial-card:hover .editorial-card-img img,
.editorial-card:focus-visible .editorial-card-img img {
  transform: scale(1.04);
}

@media (prefers-reduced-motion: reduce) {
  .editorial-card:hover .editorial-card-img img,
  .editorial-card:focus-visible .editorial-card-img img {
    transform: none;
  }
}

.editorial-card-body {
  padding: 1.25rem;
}

.editorial-tag {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(232,177,79,.1);
  border-radius: 9999px;
  padding: .15rem .55rem;
  margin-bottom: .625rem;
}

.editorial-title {
  font-size: 1.0625rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-primary);
  margin-bottom: .375rem;
}

.editorial-grid li:first-child .editorial-title {
  font-size: 1.375rem;
}

.editorial-excerpt {
  font-size: .875rem;
  color: var(--text-muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  margin-top: .75rem;
  font-size: .8rem;
  color: var(--text-faint);
}

/* ── Newsletter banner ─────────────────────────────────────────── */
.newsletter-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
  padding-block: clamp(3rem, 6vw, 4.5rem);
}

.newsletter-eyebrow {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .5rem;
}

.newsletter-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .75rem;
}

.newsletter-desc {
  font-size: .9375rem;
  color: var(--text-muted);
}

.newsletter-form { display: flex; flex-direction: column; gap: 1rem; }

.form-group { display: flex; flex-direction: column; gap: .375rem; }

.form-label {
  font-size: .875rem;
  font-weight: 600;
  color: var(--text-primary);
}

.form-input-row {
  display: flex;
  gap: .5rem;
}

.form-input {
  flex: 1;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: .9375rem;
  padding: .6875rem 1rem;
  outline: none;
  transition: border-color var(--transition);
}

.form-input::placeholder { color: var(--text-faint); }

.form-input:focus { border-color: var(--accent); }

.form-disclaimer {
  font-size: .8125rem;
  color: var(--text-faint);
}

.form-disclaimer a {
  color: var(--text-muted);
  text-decoration: underline;
}

/* ── Promo banner ─────────────────────────────────────────────── */
.promo-banner {
  background: linear-gradient(90deg, rgba(232,177,79,.12) 0%, rgba(180,79,219,.08) 100%);
  border-bottom: 1px solid rgba(232,177,79,.2);
  padding-block: .625rem;
  text-align: center;
  font-size: .875rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  position: relative;
}

.promo-banner em { font-style: normal; color: var(--accent); }

.promo-dismiss {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: .25rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  line-height: 1;
}

.promo-dismiss:hover, .promo-dismiss:focus-visible {
  color: var(--text-primary);
}

/* ── Footer ───────────────────────────────────────────────────── */
.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding-block: clamp(2.5rem, 5vw, 4rem) 1.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 2.5rem 2rem;
  margin-bottom: 3rem;
}

.footer-brand { max-width: 280px; }

.footer-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  color: var(--text-primary);
  font-size: 1.125rem;
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .875rem;
}

.footer-logo svg { color: var(--accent); }

.footer-tagline {
  font-size: .875rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

.social-links {
  display: flex;
  gap: .5rem;
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  text-decoration: none;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}

.social-link:hover, .social-link:focus-visible {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-hover);
}

.footer-col-title {
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.footer-links a {
  font-size: .9rem;
  color: var(--text-muted);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-links a:hover, .footer-links a:focus-visible {
  color: var(--accent);
  text-decoration: underline;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
}

.footer-copy {
  font-size: .8125rem;
  color: var(--text-faint);
}

.footer-legal {
  list-style: none;
  display: flex;
  gap: 1.25rem;
}

.footer-legal a {
  font-size: .8125rem;
  color: var(--text-faint);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-legal a:hover, .footer-legal a:focus-visible {
  color: var(--text-muted);
  text-decoration: underline;
}

/* ── Cart announcement ────────────────────────────────────────── */
.cart-toast {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  background: var(--bg-raised);
  border: 1px solid var(--accent);
  border-radius: var(--radius-lg);
  padding: 1rem 1.25rem;
  color: var(--text-primary);
  font-size: .9rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: .75rem;
  box-shadow: var(--shadow-card);
  z-index: 200;
  opacity: 0;
  transform: translateY(.5rem);
  transition: opacity .2s ease, transform .2s ease;
  pointer-events: none;
}

.cart-toast.visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

@media (prefers-reduced-motion: reduce) {
  .cart-toast { transition: none; }
}

/* ── Responsive ───────────────────────────────────────────────── */
@media (max-width: 900px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .hero .container { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-grid li:first-child { grid-row: auto; }
  .editorial-grid li:first-child .editorial-card-img { aspect-ratio: 3/2; height: auto; }
